    transition: 'all .3s ease',
    boxShadow: '0 6px 22px rgba(10,65,70,.06)'
  },
  courseImageWrapper: {
    height: '190px',
    position: 'relative',
    overflow: 'hidden'
  },
  courseImage: {
    width: '100%',
    height: '100%',
    objectFit: 'cover',
    display: 'block',
    transition: 'transform .5s ease'
  },
  courseTag: {
    position: 'absolute',
    top: '15px',
    left: '15px',
    color: '#ffffff',
    padding: '7px 11px',
    borderRadius: '18px',
    fontSize: '10px',
    fontWeight: 800,
    letterSpacing: '.5px'
  },
  courseImageBottom: {
    position: 'absolute',
    bottom: '12px',
    right: '12px',
    background: 'rgba(0,0,0,.55)',
    color: '#ffffff',
    padding: '5px 9px',
    borderRadius: '8px',
    fontSize: '9px',
    fontWeight: 700
  },
  courseBody: {
    padding: '21px'
  },
  courseName: {
    color: '#103d45',
    fontSize: '19px',
    lineHeight: 1.35,
    margin: '0 0 14px',
    fontWeight: 800
  },
  techTags: {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '7px',
    marginBottom: '16px'
  },
  techTag: {
    background: '#edf7f5',
    color: '#17675f',
    borderRadius: '7px',
    padding: '5px 8px',
    fontSize: '10px',
    fontWeight: 700
  },
  ratingRow: {
    display: 'flex',
    alignItems: 'center',
    flexWrap: 'wrap',
    gap: '5px',
    marginBottom: '18px'
  },
  ratingStars: {
    color: '#e6a91a',
    fontSize: '13px',
    letterSpacing: '1px'
  },
  ratingNumber: {
    color: '#274950',
    fontSize: '13px'
  },
  ratingCount: {
    color: '#819095',
    fontSize: '11px'
  },
  priceRow: {
    borderTop: '1px solid #edf1f1',
    paddingTop: '16px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    gap: '10px'
  },
  currentPrice: {
    color: '#087f73',
    fontSize: '23px',
    fontWeight: 800,
    marginRight: '8px'
  },
  oldPrice: {
    color: '#9ba8ab',
    textDecoration: 'line-through',
    fontSize: '12px'
  },
  registerBtn: {
    background: '#ffffff',
    color: '#087f73',
    border: '1px solid #087f73',
    padding: '9px 13px',
    borderRadius: '20px',
    fontSize: '11px',
    fontWeight: 800,
    cursor: 'pointer',
    transition: 'all .25s ease'
  },
  testimonialsGrid: {
    maxWidth: '1100px',
    margin: '0 auto',
    display: 'grid',
    gridTemplateColumns: 'repeat(3,1fr)',
    gap: '25px'
  },
  testimonialCard: {
    position: 'relative',
    background: '#ffffff',
    border: '1px solid #dbeae8',
    borderRadius: '20px',
    padding: '30px',
    transition: 'all .3s ease'
  },
  quoteMark: {
    color: '#d4ebe7',
    fontFamily: 'Georgia,serif',
    fontSize: '65px',
    lineHeight: '.7',
    height: '40px'
  },
  testimonialQuote: {
    color: '#4e6268',
    fontSize: '14px',
    lineHeight: 1.7,
    minHeight: '105px',
    margin: '10px 0 22px'
  },
  testimonialUser: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px'
  },
  avatar: {
    width: '48px',
    height: '48px',
    borderRadius: '50%',
    objectFit: 'cover',
    border: '3px solid #dff1ee'
  },
  userName: {
    color: '#103e45',
    fontSize: '15px',
    margin: 0,
    fontWeight: 800
  },
  userRole: {
    color: '#819095',
    fontSize: '12px',
    margin: '4px 0 0'
  },
  stars: {
    color: '#e8ae23',
    fontSize: '14px',
    marginTop: '17px',
    letterSpacing: '2px'
  },
  learningSection: {
    padding: '70px 6%',
    background: 'linear-gradient(135deg,#043f43,#087f73 60%,#075c58)',
    color: '#ffffff'
  },
  learningContent: {
    maxWidth: '1200px',
    margin: '0 auto',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: '35px'
  },
  learningEyebrow: {
    color: '#f3c55d',
    fontSize: '12px',
    fontWeight: 800,
    letterSpacing: '3px'
  },
  learningTitle: {
    fontFamily: "'Playfair Display',Georgia,serif",
    fontSize: '40px',
    margin: '10px 0 12px',
    lineHeight: 1.2
  },
  learningSubtitle: {
    color: '#d3ece9',
    fontSize: '15px',
    lineHeight: 1.7,
    margin: 0,
    maxWidth: '650px'
  },
  learningAction: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    gap: '10px',
    minWidth: '220px'
  },
  learningButton: {
    border: 'none',
    background: '#f2bf4f',
    color: '#143b40',
    padding: '15px 25px',
    borderRadius: '28px',
    fontSize: '15px',
    fontWeight: 800,
    cursor: 'pointer',
    transition: 'all .3s ease'
  },
  limitedText: {
    color: '#d8efec',
    fontSize: '11px'
  }
};
var _c;
$RefreshReg$(_c, "Home");

sourcesContent:
import React from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../components/Header';
import Footer from '../components/Footer';

export default function Home() {
  const navigate = useNavigate();

  const categories = [
    { icon: '💻', title: 'Web Development', sub: 'Full Stack', image: 'https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&w=700&q=80' },
    { icon: '🐍', title: 'Python', sub: 'Programming', image: 'https://images.unsplash.com/photo-1526379095098-d400fd0bf935?auto=format&fit=crop&w=700&q=80' },
    { icon: '☕', title: 'Java', sub: 'Development', image: 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?auto=format&fit=crop&w=700&q=80' },
    { icon: '📊', title: 'Data Science', sub: '& Analytics', image: 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=700&q=80' },
    { icon: '🤖', title: 'Artificial Intelligence', sub: '& Machine Learning', image: 'https://images.unsplash.com/photo-1677442136019-21780ecad995?auto=format&fit=crop&w=700&q=80' },
    { icon: '☁️', title: 'Cloud Computing', sub: 'AWS | Azure', image: 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=700&q=80' },
    { icon: '📱', title: 'Mobile App', sub: 'Development', image: 'https://images.unsplash.com/photo-1551650975-87deedd944c3?auto=format&fit=crop&w=700&q=80' },
    { icon: '🛡️', title: 'Cyber Security', sub: 'Security & Ethical Hacking', image: 'https://images.unsplash.com/photo-1563013544-824ae1b704d3?auto=format&fit=crop&w=700&q=80' }
  ];

  const features = [
    { icon: '🎓', title: 'Industry Expert Trainers', desc: 'Learn directly from experienced professionals with real-world knowledge.' },
    { icon: '🎥', title: 'Live & Recorded Classes', desc: 'Attend interactive live classes and access recordings whenever you need.' },
    { icon: '⚙️', title: 'Hands-on Projects', desc: 'Build practical projects that strengthen your portfolio and skills.' },
    { icon: '💳', title: 'Affordable Learning', desc: 'Get professional-quality technical education at affordable prices.' },
    { icon: '🏆', title: 'Career Certification', desc: 'Earn certificates that showcase your skills to employers.' }
  ];

  const courses = [
    {
      title: 'Java Full Stack Development',
      image: 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=900&q=80',
      tag: 'BESTSELLER',
      tagColor: '#087f73',
      tags: ['Java', 'Spring Boot', 'React', 'MySQL'],
      rating: '4.9',
      learners: '2,340',
      price: '₹9',
      oldPrice: '₹999'
    },
    {
      title: 'Python Full Stack Development',
      image: 'https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=900&q=80',
      tag: 'POPULAR',
      tagColor: '#2563eb',
      tags: ['Python', 'Django', 'React', 'SQL'],
      rating: '4.9',
      learners: '3,120',
      price: '₹9',
      oldPrice: '₹1,499'
    },
    {
      title: 'Generative AI & Machine Learning',
      image: 'https://images.unsplash.com/photo-1555255707-c07966088b7b?auto=format&fit=crop&w=900&q=80',
      tag: 'TRENDING',
      tagColor: '#7c3aed',
      tags: ['Gen AI', 'LLM', 'Python', 'Agents'],
      rating: '4.8',
      learners: '1,980',
      price: '₹9',
      oldPrice: '₹1,899'
    },
    {
      title: 'Data Analyst Professional',
      image: 'https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=900&q=80',
      tag: 'NEW',
      tagColor: '#059669',
      tags: ['Excel', 'SQL', 'Power BI', 'Python'],
      rating: '4.8',
      learners: '1,540',
      price: '₹9',
      oldPrice: '₹1,499'
    }
  ];

  const testimonials = [
    {
      quote: 'Amazing teaching style and real-time examples. I got placed as a software engineer after completing the course!',
      name: 'Rahul K.',
      role: 'Software Engineer',
      image: 'https://randomuser.me/api/portraits/men/32.jpg'
    },
    {
      quote: 'Vighnavi Academy helped me build confidence in Python and Data Science. Highly recommended!',
      name: 'Divya S.',
      role: 'Data Analyst',
      image: 'https://randomuser.me/api/portraits/women/44.jpg'
    },
    {
      quote: 'Affordable and high-quality courses. The practical projects helped me understand concepts much faster.',
      name: 'Suresh M.',
      role: 'Cloud Engineer',
      image: 'https://randomuser.me/api/portraits/men/46.jpg'
    }
  ];

  return (
    <div style={styles.container}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700;800&display=swap');
        *{box-sizing:border-box}
        html{scroll-behavior:smooth}
        body{margin:0}
        .home-btn:hover{transform:translateY(-3px);box-shadow:0 12px 28px rgba(15,118,110,.25)}
        .watch-btn:hover{background:#0f766e!important;color:#fff!important;transform:translateY(-3px)}
        .category-card:hover{transform:translateY(-8px);box-shadow:0 18px 40px rgba(15,118,110,.14)!important;border-color:#99d8d1!important}
        .feature-card:hover{transform:translateY(-7px);box-shadow:0 18px 35px rgba(15,118,110,.12)!important}
        .course-card:hover{transform:translateY(-8px);box-shadow:0 20px 45px rgba(15,118,110,.16)!important}
        .course-card:hover img{transform:scale(1.06)}
        .register-btn:hover{background:#0f766e!important;color:#fff!important}
        .view-btn:hover{background:#0f766e!important;color:#fff!important}
        .testimonial-card:hover{transform:translateY(-6px);box-shadow:0 18px 35px rgba(15,118,110,.12)!important}
        .float-badge{animation:float 4s ease-in-out infinite}
        .float-badge:nth-child(2){animation-delay:.5s}
        .float-badge:nth-child(3){animation-delay:1s}
        .float-badge:nth-child(4){animation-delay:1.5s}
        @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}
        @keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(245,183,65,.35)}50%{box-shadow:0 0 0 12px rgba(245,183,65,0)}}
        .hero-main-image{animation:pulse 3s infinite}
        @media(max-width:1000px){
          .hero-section{flex-direction:column!important;padding:70px 30px!important}
          .hero-content{max-width:850px!important}
          .hero-image-container{width:100%!important;max-width:700px}
          .stats-container{flex-wrap:wrap}
        }
        @media(max-width:700px){
          .hero-section{padding:50px 20px!important}
          .hero-title{font-size:40px!important}
          .hero-description{font-size:16px!important}
          .hero-buttons{flex-direction:column!important}
          .stats-container{display:grid!important;grid-template-columns:1fr 1fr!important}
          .stat-divider{display:none!important}
          .section{padding:55px 18px!important}
          .section-title{font-size:32px!important}
          .categories-grid{grid-template-columns:1fr 1fr!important}
          .courses-grid{grid-template-columns:1fr!important}
          .features-grid{grid-template-columns:1fr!important}
          .testimonials-grid{grid-template-columns:1fr!important}
          .bottom-content{flex-direction:column!important;text-align:center!important}
          .floating-badge{display:none!important}
        }
        @media(max-width:450px){
          .categories-grid{grid-template-columns:1fr!important}
          .hero-title{font-size:34px!important}
          .stats-container{grid-template-columns:1fr!important}
        }
      `}</style>

      <Header />

      <section className="hero-section" style={styles.heroSection}>
        <div className="hero-content" style={styles.heroContent}>
          <div style={styles.heroBadge}>
            <span>🎓 Learn Anytime • Anywhere</span>
          </div>
          <h1 className="hero-title" style={styles.heroTitle}>
            Build Your Future
            <br />
            with <span style={styles.highlightText}>Vighnavi Academy</span>
          </h1>
          <p style={styles.heroSubtitle}>
            India's Trusted Online Technical Training Academy
          </p>
          <p className="hero-description" style={styles.heroDesc}>
            Acquire in-demand skills, get certified and accelerate your career
            with industry-focused online courses, practical projects and expert
            mentorship.
          </p>

          <div className="hero-buttons" style={styles.heroButtons}>
            <button
              className="home-btn"
              style={styles.exploreBtn}
              onClick={() => navigate('/courses')}
            >
              Explore Courses <span>→</span>
            </button>
            <button className="watch-btn" style={styles.watchBtn}>
              <span style={styles.playIcon}>▶</span>
              Watch Intro
            </button>
          </div>

          <div className="stats-container" style={styles.statsContainer}>
            <div style={styles.statItem}>
              <h3 style={styles.statNum}>10K+</h3>
              <p style={styles.statLabel}>Happy Learners</p>
            </div>
            <div className="stat-divider" style={styles.statDivider}></div>
            <div style={styles.statItem}>
              <h3 style={styles.statNum}>100+</h3>
              <p style={styles.statLabel}>Expert Trainers</p>
            </div>
            <div className="stat-divider" style={styles.statDivider}></div>
            <div style={styles.statItem}>
              <h3 style={styles.statNum}>250+</h3>
              <p style={styles.statLabel}>Professional Courses</p>
            </div>
            <div className="stat-divider" style={styles.statDivider}></div>
            <div style={styles.statItem}>
              <h3 style={styles.statNum}>95%</h3>
              <p style={styles.statLabel}>Placement Support</p>
            </div>
          </div>
        </div>

        <div className="hero-image-container" style={styles.heroImageContainer}>
          <div className="float-badge floating-badge" style={styles.badgeOne}>
            💻 Full Stack
          </div>
          <div className="float-badge floating-badge" style={styles.badgeTwo}>
            🐍 Python
          </div>
          <div className="float-badge floating-badge" style={styles.badgeThree}>
            ☕ Java
          </div>
          <div className="float-badge floating-badge" style={styles.badgeFour}>
            🤖 Generative AI
          </div>

          <div className="hero-main-image" style={styles.heroImageCard}>
            <img
              src="https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1100&q=85"
              alt="Students learning technology"
              style={styles.heroImage}
            />
            <div style={styles.imageOverlay}></div>
            <div style={styles.imageText}>
              <span style={styles.imageSmallText}>VIGHNAVI ACADEMY</span>
              <strong>Learn • Build • Grow</strong>
              <span>Shape your future with technology</span>
            </div>
          </div>
        </div>
      </section>

      <section className="section" style={styles.section}>
        <div style={styles.sectionHeader}>
          <span style={styles.eyebrow}>LEARN WHAT MATTERS</span>
          <h2 className="section-title" style={styles.sectionTitle}>
            Explore Top Categories <span>🎓</span>
          </h2>
          <p style={styles.sectionSubtitle}>
            Choose the skills you need for a brighter future
          </p>
        </div>

        <div className="categories-grid" style={styles.categoriesGrid}>
          {categories.map((cat, index) => (
            <div
              className="category-card"
              key={index}
              style={styles.categoryCard}
            >
              <div style={styles.categoryImageWrapper}>
                <img
                  src={cat.image}
                  alt={cat.title}
                  style={styles.categoryImage}
                />
                <div style={styles.categoryIcon}>{cat.icon}</div>
              </div>
              <h4 style={styles.catTitle}>{cat.title}</h4>
              <p style={styles.catSub}>{cat.sub}</p>
            </div>
          ))}
        </div>
      </section>

      <section style={styles.sectionAlt}>
        <div style={styles.sectionHeader}>
          <span style={styles.eyebrow}>WHY VIGHNAVI ACADEMY</span>
          <h2 className="section-title" style={styles.sectionTitle}>
            Learn Today. <span style={styles.highlightText}>Lead Tomorrow.</span>
          </h2>
          <p style={styles.sectionSubtitle}>
            Everything you need to become industry-ready
          </p>
        </div>

        <div className="features-grid" style={styles.featuresGrid}>
          {features.map((feature, index) => (
            <div
              className="feature-card"
              key={index}
              style={styles.featureCard}
            >
              <div style={styles.featureIcon}>{feature.icon}</div>
              <h4 style={styles.featureTitle}>{feature.title}</h4>
              <p style={styles.featureDesc}>{feature.desc}</p>
            </div>
          ))}
        </div>
      </section>

      <section className="section" style={styles.section}>
        <div className="courses-header" style={styles.coursesHeader}>
          <div>
            <span style={styles.eyebrow}>CAREER-FOCUSED COURSES</span>
            <h2 className="section-title" style={styles.sectionTitle}>
              Popular Courses <span>🔥</span>
            </h2>
            <p style={styles.sectionSubtitle}>
              Build practical skills with our most popular programs
            </p>
          </div>
          <button
            className="view-btn"
            style={styles.viewAllBtn}
            onClick={() => navigate('/courses')}
          >
            View All Courses →
          </button>
        </div>

        <div className="courses-grid" style={styles.coursesGrid}>
          {courses.map((course, index) => (
            <div
              className="course-card"
              key={index}
              style={styles.courseCard}
            >
              <div style={styles.courseImageWrapper}>
                <img
                  src={course.image}
                  alt={course.title}
                  style={styles.courseImage}
                />
                <span
                  style={{
                    ...styles.courseTag,
                    backgroundColor: course.tagColor
                  }}
                >
                  ★ {course.tag}
                </span>
                <div style={styles.courseImageBottom}>
                  <span>Vighnavi Academy</span>
                </div>
              </div>

              <div style={styles.courseBody}>
                <h3 style={styles.courseName}>{course.title}</h3>

                <div style={styles.techTags}>
                  {course.tags.map((tag, tagIndex) => (
                    <span key={tagIndex} style={styles.techTag}>
                      {tag}
                    </span>
                  ))}
                </div>

                <div style={styles.ratingRow}>
                  <span style={styles.ratingStars}>★★★★★</span>
                  <strong style={styles.ratingNumber}>{course.rating}</strong>
                  <span style={styles.ratingCount}>
                    ({course.learners} learners)
                  </span>
                </div>

                <div style={styles.priceRow}>
                  <div>
                    <span style={styles.currentPrice}>{course.price}</span>
                    <span style={styles.oldPrice}>{course.oldPrice}</span>
                  </div>
                  <button
                    className="register-btn"
                    style={styles.registerBtn}
                    onClick={() => navigate('/contact')}
                  >
                    Register →
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      <section style={styles.sectionAlt}>
        <div style={styles.sectionHeader}>
          <span style={styles.eyebrow}>STUDENT SUCCESS</span>
          <h2 className="section-title" style={styles.sectionTitle}>
            What Our Learners Say <span>💙</span>
          </h2>
          <p style={styles.sectionSubtitle}>
            Real experiences from learners building their careers
          </p>
        </div>

        <div className="testimonials-grid" style={styles.testimonialsGrid}>
          {testimonials.map((testimonial, index) => (
            <div
              className="testimonial-card"
              key={index}
              style={styles.testimonialCard}
            >
              <div style={styles.quoteMark}>“</div>
              <p style={styles.testimonialQuote}>
                {testimonial.quote}
              </p>
              <div style={styles.testimonialUser}>
                <img
                  src={testimonial.image}
                  alt={testimonial.name}
                  style={styles.avatar}
                />
                <div>
                  <h4 style={styles.userName}>{testimonial.name}</h4>
                  <p style={styles.userRole}>{testimonial.role}</p>
                </div>
              </div>
              <div style={styles.stars}>★★★★★</div>
            </div>
          ))}
        </div>
      </section>

      <section style={styles.learningSection}>
        <div
          className="bottom-content"
          style={styles.learningContent}
        >
          <div>
            <span style={styles.learningEyebrow}>YOUR FUTURE STARTS HERE</span>
            <h2 style={styles.learningTitle}>
              Start Your Learning Journey Today!
            </h2>
            <p style={styles.learningSubtitle}>
              Join thousands of learners building their dream careers with
              Vighnavi Academy.
            </p>
          </div>

          <div style={styles.learningAction}>
            <button
              className="home-btn"
              style={styles.learningButton}
              onClick={() => navigate('/courses')}
            >
              Explore Courses →
            </button>
            <span style={styles.limitedText}>
              ✦ Industry-focused learning
            </span>
          </div>
        </div>
      </section>

      <Footer />
    </div>
  );
}

const styles = {
  container: {
    fontFamily: "'Inter',Arial,sans-serif",
    backgroundColor: '#f7fbfa',
    color: '#10343b',
    overflowX: 'hidden'
  },
  heroSection: {
    minHeight: '680px',
    padding: '75px 6%',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    gap: '55px',
    background: 'linear-gradient(135deg,#eaf8f6 0%,#ffffff 48%,#dff3ef 100%)',
    position: 'relative',
    overflow: 'hidden'
  },
  heroContent: {
    flex: 1,
    maxWidth: '650px',
    position: 'relative',
    zIndex: 2
  },
  heroBadge: {
    display: 'inline-flex',
    alignItems: 'center',
    padding: '10px 18px',
    borderRadius: '30px',
